#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <float.h>

#define MAX_N 1000

typedef struct {
    double x, y;
    int idx; // original index
    int visited;
} Point;

// compute angle from (dx, dy) relative to reference direction
// returns angle in [0, 2*PI)
double angle_from(double dx, double dy, double ref_dx, double ref_dy) {
    double dot = dx * ref_dx + dy * ref_dy;
    double cross = dx * ref_dy - dy * ref_dx;
    double ang = atan2(cross, dot); // in [-PI, PI]
    if (ang < 0) ang += 2 * M_PI;
    return ang;
}

int main() {
    int dataset = 0;
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        dataset++;
        Point points[MAX_N];
        for (int i = 0; i < n; i++) {
            scanf("%lf %lf", &points[i].x, &points[i].y);
            points[i].idx = i;
            points[i].visited = 0;
        }

        double cur_x = 0.0, cur_y = 0.0;
        double dir_x = 0.0, dir_y = 1.0; // facing north
        double total_dist = 0.0;

        for (int step = 0; step < n; step++) {
            int best_idx = -1;
            double best_angle = DBL_MAX;
            double best_dist = DBL_MAX;

            for (int i = 0; i < n; i++) {
                if (points[i].visited) continue;
                double dx = points[i].x - cur_x;
                double dy = points[i].y - cur_y;
                double dist = sqrt(dx*dx + dy*dy);
                if (dist < 1e-12) continue; // skip if same point (shouldn't happen)
                double ang = angle_from(dx, dy, dir_x, dir_y);
                if (ang < best_angle - 1e-12 ||
                    (fabs(ang - best_angle) < 1e-12 && dist < best_dist - 1e-12)) {
                    best_angle = ang;
                    best_dist = dist;
                    best_idx = i;
                }
            }

            if (best_idx == -1) break; // shouldn't happen

            // move to best_idx
            double dx = points[best_idx].x - cur_x;
            double dy = points[best_idx].y - cur_y;
            total_dist += sqrt(dx*dx + dy*dy);
            cur_x = points[best_idx].x;
            cur_y = points[best_idx].y;
            // update direction to vector from previous to current
            dir_x = dx;
            dir_y = dy;
            double len = sqrt(dir_x*dir_x + dir_y*dir_y);
            if (len > 1e-12) {
                dir_x /= len;
                dir_y /= len;
            }
            points[best_idx].visited = 1;
        }

        printf("Dataset %d: %.3f\n", dataset, total_dist);
    }
    return 0;
}

