#define MAXN 105
#define PI 3.14159265358979323846

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        double x[MAXN], y[MAXN];
        for (int i = 0; i < n; i++) {
            scanf("%lf %lf", &x[i], &y[i]);
        }

        int visited[MAXN];
        memset(visited, 0, sizeof(visited));

        double cx = 0, cy = 0;
        // facing north: direction (0, 1)
        double dx = 0, dy = 1;
        double total = 0;

        for (int step = 0; step < n; step++) {
            double best_angle = 1e18;
            double best_dist = 1e18;
            int best = -1;

            double dir_angle = atan2(dy, dx);

            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                double vx = x[i] - cx;
                double vy = y[i] - cy;
                double dist = sqrt(vx*vx + vy*vy);
                double flag_angle = atan2(vy, vx);

                double cw_angle = dir_angle - flag_angle;
                while (cw_angle < 0) cw_angle += 2*PI;
                while (cw_angle >= 2*PI) cw_angle -= 2*PI;

                if (cw_angle < best_angle - 1e-9 || 
                    (fabs(cw_angle - best_angle) < 1e-9 && dist < best_dist - 1e-9)) {
                    best_angle = cw_angle;
                    best_dist = dist;
                    best = i;
                }
            }

            total += best_dist;
            dx = x[best] - cx;
            dy = y[best] - cy;
            double len = sqrt(dx*dx + dy*dy);
            dx /= len; dy /= len;
            cx = x[best];
            cy = y[best];
            visited[best] = 1;
        }

        printf("%.2f\n", total);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef long long ll;

typedef struct {
    ll x, y;
} Point;

static Point pivot;

static ll cross(Point a, Point b, Point c) {
    /* (b-a) x (c-a) */
    ll x1 = b.x - a.x, y1 = b.y - a.y;
    ll x2 = c.x - a.x, y2 = c.y - a.y;
    return x1 * y2 - y1 * x2;
}

static ll dist2(Point a, Point b) {
    ll dx = a.x - b.x, dy = a.y - b.y;
    return dx * dx + dy * dy;
}

static int cmp_points(const void *pa, const void *pb) {
    Point a = *(const Point *)pa;
    Point b = *(const Point *)pb;

    ll cr = cross(pivot, a, b);
    if (cr > 0) return -1;
    if (cr < 0) return 1;

    ll da = dist2(pivot, a);
    ll db = dist2(pivot, b);
    if (da < db) return -1;
    if (da > db) return 1;
    if (a.x != b.x) return (a.x < b.x) ? -1 : 1;
    if (a.y != b.y) return (a.y < b.y) ? -1 : 1;
    return 0;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        Point *p = (Point *)malloc(sizeof(Point) * n);
        for (int i = 0; i < n; i++) {
            scanf("%lld %lld", &p[i].x, &p[i].y);
        }

        /* Start at origin, initially facing north.
           Equivalent ordering:
           - sort by polar angle around origin starting from +Y clockwise
           - for same ray, nearest first
           This can be done by sorting CCW from pivot after rotating coordinates:
           (x, y) -> (-y, x), which maps +Y to +X.
        */
        Point *q = (Point *)malloc(sizeof(Point) * n);
        for (int i = 0; i < n; i++) {
            q[i].x = -p[i].y;
            q[i].y =  p[i].x;
        }

        pivot.x = 0;
        pivot.y = 0;
        qsort(q, n, sizeof(Point), cmp_points);

        double ans = 0.0;
        Point cur = {0, 0};

        for (int i = 0; i < n; i++) {
            Point real;
            /* inverse rotation: (u, v) -> (v, -u) */
            real.x = q[i].y;
            real.y = -q[i].x;

            double dx = (double)real.x - (double)cur.x;
            double dy = (double)real.y - (double)cur.y;
            ans += sqrt(dx * dx + dy * dy);

            cur = real;
        }

        printf("%.3f\n", ans);

        free(p);
        free(q);
    }
    return 0;
}

