struct Point {
    long long x, y;
};

// cross product of vectors (p2-p1) and (p3-p1)
long long cross(const Point &p1, const Point &p2, const Point &p3) {
    return (p2.x - p1.x) * (p3.y - p1.y) - (p2.y - p1.y) * (p3.x - p1.x);
}

// dot product
long long dot(const Point &p1, const Point &p2, const Point &p3) {
    return (p2.x - p1.x) * (p3.x - p1.x) + (p2.y - p1.y) * (p3.y - p1.y);
}

long long dist2(const Point &a, const Point &b) {
    long long dx = a.x - b.x, dy = a.y - b.y;
    return dx*dx + dy*dy;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n && n != 0) {
        vector<Point> flags(n);
        for (int i = 0; i < n; i++) {
            cin >> flags[i].x >> flags[i].y;
        }

        vector<bool> visited(n, false);
        Point cur = {0, 0};
        int dirx = 0, diry = 1; // facing north
        double totalDist = 0.0;

        for (int step = 0; step < n; step++) {
            int best = -1;
            long long bestCross = -1; // cross product relative to current direction
            long long bestDist = LLONG_MAX;
            long long bestDot = LLONG_MAX;

            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                long long dx = flags[i].x - cur.x;
                long long dy = flags[i].y - cur.y;
                long long cr = (long long)dirx * dy - (long long)diry * dx; // cross with direction vector

                if (cr < 0) continue; // not to the right

                long long d2 = dx*dx + dy*dy;
                long long dt = (long long)dirx * dx + (long long)diry * dy;

                if (cr == 0) {
                    // collinear: choose closest
                    if (d2 < bestDist) {
                        bestDist = d2;
                        best = i;
                        bestCross = cr;
                        bestDot = dt;
                    }
                } else {
                    if (best == -1 || cr < bestCross || (cr == bestCross && dt < bestDot) || 
                        (cr == bestCross && dt == bestDot && d2 < bestDist)) {
                        bestCross = cr;
                        bestDot = dt;
                        bestDist = d2;
                        best = i;
                    }
                }
            }

            if (best == -1) break; // should not happen

            visited[best] = true;
            totalDist += sqrt((double)dist2(cur, flags[best]));
            // update direction
            dirx = flags[best].x - cur.x;
            diry = flags[best].y - cur.y;
            cur = flags[best];
        }

        cout << fixed << setprecision(2) << totalDist << "\n";
    }

    return 0;
}

