#include <bits/stdc++.h>
using namespace std;

struct Point {
    long long x, y;
};

static inline long long cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

static inline long long dist2(const Point& a, const Point& b) {
    long long dx = a.x - b.x;
    long long dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cout.setf(ios::fixed);
    cout << setprecision(3);

    while (cin >> n && n) {
        vector<Point> p(n);
        for (int i = 0; i < n; ++i) cin >> p[i].x >> p[i].y;

        vector<bool> used(n, false);
        Point cur{0, 0};
        Point dir{0, 1}; // initially facing north
        double total = 0.0;

        for (int step = 0; step < n; ++step) {
            int best = -1;

            for (int i = 0; i < n; ++i) {
                if (used[i]) continue;
                if (best == -1) {
                    best = i;
                    continue;
                }

                Point vb{p[best].x - cur.x, p[best].y - cur.y};
                Point vi{p[i].x - cur.x, p[i].y - cur.y};

                long long cb = dir.x * vb.y - dir.y * vb.x;
                long long ci = dir.x * vi.y - dir.y * vi.x;

                bool rightB = cb < 0;
                bool rightI = ci < 0;

                // Sort vectors by clockwise angle from current direction:
                // first those to the right (negative cross), then collinear/front,
                // then to the left; within same half use cross comparison.
                auto half = [](long long c) -> int {
                    if (c < 0) return 0;
                    if (c == 0) return 1;
                    return 2;
                };

                int hb = half(cb), hi = half(ci);

                bool better = false;
                if (hi != hb) {
                    better = hi < hb;
                } else {
                    long long cr = vb.x * vi.y - vb.y * vi.x;
                    if (cr != 0) {
                        // smaller clockwise angle comes first
                        better = cr < 0;
                    } else {
                        // same direction: nearer first
                        better = dist2(cur, p[i]) < dist2(cur, p[best]);
                    }
                }

                if (better) best = i;
            }

            total += sqrt((double)dist2(cur, p[best]));
            dir = {p[best].x - cur.x, p[best].y - cur.y};
            cur = p[best];
            used[best] = true;
        }

        cout << total << "\n";
    }

    return 0;
}

