public class Footrace {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        boolean first = true;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            int n = Integer.parseInt(line);
            if (n == 0) break;
            if (!first) System.out.println();
            first = false;

            List<double[]> flags = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                double x = Double.parseDouble(st.nextToken());
                double y = Double.parseDouble(st.nextToken());
                flags.add(new double[]{x, y});
            }

            boolean[] visited = new boolean[n];
            double cx = 0, cy = 0;
            double dirX = 0, dirY = 1; // facing north
            double totalDist = 0;

            for (int step = 0; step < n; step++) {
                int nextIdx = -1;
                double bestAngle = Double.MAX_VALUE;
                double bestDist = Double.MAX_VALUE;

                for (int i = 0; i < n; i++) {
                    if (visited[i]) continue;
                    double dx = flags.get(i)[0] - cx;
                    double dy = flags.get(i)[1] - cy;
                    double dist = Math.sqrt(dx * dx + dy * dy);

                    // angle from current direction (clockwise positive)
                    double angle = Math.atan2(dirX * dy - dirY * dx, dirX * dx + dirY * dy);
                    if (angle < 0) angle += 2 * Math.PI; // normalize to [0, 2π)

                    if (angle < bestAngle - 1e-12 || (Math.abs(angle - bestAngle) < 1e-12 && dist < bestDist)) {
                        bestAngle = angle;
                        bestDist = dist;
                        nextIdx = i;
                    }
                }

                visited[nextIdx] = true;
                double dx = flags.get(nextIdx)[0] - cx;
                double dy = flags.get(nextIdx)[1] - cy;
                totalDist += Math.sqrt(dx * dx + dy * dy);

                // update direction to the line from current to next flag
                dirX = flags.get(nextIdx)[0] - cx;
                dirY = flags.get(nextIdx)[1] - cy;
                double len = Math.sqrt(dirX * dirX + dirY * dirY);
                if (len > 0) {
                    dirX /= len;
                    dirY /= len;
                }

                cx = flags.get(nextIdx)[0];
                cy = flags.get(nextIdx)[1];
            }

            System.out.printf("%.2f%n", totalDist);
        }
    }
}

