public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            double[][] flags = new double[n][2];
            for (int i = 0; i < n; i++) {
                flags[i][0] = sc.nextDouble();
                flags[i][1] = sc.nextDouble();
            }

            boolean[] visited = new boolean[n];
            double cx = 0, cy = 0;
            double heading = 0.0; // North = 0 degrees
            double totalDist = 0.0;

            for (int step = 0; step < n; step++) {
                // Find next flag: smallest clockwise angle from heading, nearest if tie
                int best = -1;
                double bestAngle = Double.MAX_VALUE;
                double bestDist = Double.MAX_VALUE;

                for (int i = 0; i < n; i++) {
                    if (visited[i]) continue;
                    double dx = flags[i][0] - cx;
                    double dy = flags[i][1] - cy;
                    double dist = Math.sqrt(dx*dx + dy*dy);
                    if (dist < 1e-12) continue;

                    // Bearing in degrees, North=0, clockwise positive
                    double bearing = Math.toDegrees(Math.atan2(dx, dy));
                    if (bearing < 0) bearing += 360;

                    // Clockwise angle from heading to bearing
                    double angle = (bearing - heading + 360) % 360;

                    if (angle < bestAngle - 1e-9 || 
                        (Math.abs(angle - bestAngle) < 1e-9 && dist < bestDist - 1e-9)) {
                        bestAngle = angle;
                        bestDist = dist;
                        best = i;
                    }
                }

                visited[best] = true;
                double dx = flags[best][0] - cx;
                double dy = flags[best][1] - cy;
                totalDist += Math.sqrt(dx*dx + dy*dy);
                // Update heading: direction we just traveled
                heading = Math.toDegrees(Math.atan2(dx, dy));
                if (heading < 0) heading += 360;
                cx = flags[best][0];
                cy = flags[best][1];
            }

            System.out.printf("%.2f%n", totalDist);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long cross(long ax, long ay, long bx, long by) {
        return ax * by - ay * bx;
    }

    static long dot(long ax, long ay, long bx, long by) {
        return ax * bx + ay * by;
    }

    static double dist(Point a, Point b) {
        long dx = a.x - b.x;
        long dy = a.y - b.y;
        return Math.sqrt((double) dx * dx + (double) dy * dy);
    }

    static boolean inRightHalf(long dx, long dy, long vx, long vy) {
        long c = cross(dx, dy, vx, vy);
        if (c < 0) return true;
        if (c > 0) return false;
        return dot(dx, dy, vx, vy) > 0;
    }

    static boolean better(long dx, long dy, Point cur, Point a, Point b) {
        long ax = a.x - cur.x, ay = a.y - cur.y;
        long bx = b.x - cur.x, by = b.y - cur.y;

        boolean ha = inRightHalf(dx, dy, ax, ay);
        boolean hb = inRightHalf(dx, dy, bx, by);

        if (ha != hb) return ha; // right-turn angles [0,180) come before (180,360)

        long cab = cross(ax, ay, bx, by);
        if (cab != 0) {
            return cab < 0; // a is clockwise from b
        }

        long da = ax * ax + ay * ay;
        long db = bx * bx + by * by;
        return da < db; // same direction: nearer first
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            Point[] pts = new Point[n];
            for (int i = 0; i < n; i++) {
                pts[i] = new Point(fs.nextInt(), fs.nextInt());
            }

            boolean[] used = new boolean[n];
            Point cur = new Point(0, 0);
            long dirx = 0, diry = 1; // initially north
            double total = 0.0;

            for (int step = 0; step < n; step++) {
                int best = -1;
                for (int i = 0; i < n; i++) {
                    if (used[i]) continue;
                    if (best == -1 || better(dirx, diry, cur, pts[i], pts[best])) {
                        best = i;
                    }
                }

                total += dist(cur, pts[best]);
                dirx = pts[best].x - cur.x;
                diry = pts[best].y - cur.y;
                cur = pts[best];
                used[best] = true;
            }

            out.append(String.format(Locale.US, "%.3f%n", total));
        }

        System.out.print(out.toString());
    }
}
